css:
.no-deployments-container {
  font-family:
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    Roboto,
    "Helvetica Neue",
    Arial,
    sans-serif;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  background-color: #ffffff;
  padding: 3rem 1.5rem;
  max-width: 20rem;
  margin: 2rem auto;
  position: relative;
  border: 1px solid #e6e4e4;
  border-radius: 0.5rem;
}

.icon-wrapper {
  margin-bottom: 1.5rem;
}

.rocket-icon {
  width: 2.5rem;
  height: 2.5rem;
  color: #0f172a;
}

.title-text {
  font-size: 1.25rem;
  font-weight: 600;
  color: #0f172a;
  margin: 0 0 0.5rem 0;
}

.description {
  font-size: 1rem;
  color: #475569;
  line-height: 1.5;
  margin: 0 0 1.5rem 0;
  max-width: 25rem;
}

.cta-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;

  background: linear-gradient(to bottom, #055ffc, #004ecc);
  color: #ffffff;
  box-shadow: 0 2px 4px rgba(5, 95, 252, 0.3);

  font-size: 0.875rem;
  font-weight: 600;

  padding: 0.625rem 1.25rem;
  border: 1px solid #0044bb;
  border-radius: 0.375rem;
  cursor: pointer;

  transition: all 0.2s ease-in-out;
  position: relative;
  overflow: visible;
}

.cta-button:hover {
  background: linear-gradient(to bottom, #004ecc, #003aa0);
  box-shadow: 0 4px 8px rgba(5, 95, 252, 0.4);
  transform: translateY(-1px);
}

/* Pulse effect */
.cta-button::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 100%;
  height: 100%;
  border-radius: 0.375rem;
  background-color: rgba(5, 95, 252, 0.3);
  transform: translate(-50%, -50%) scale(1);
  opacity: 0;
  pointer-events: none;
}

.deploy-checkbox:checked ~ .description ~ .cta-button::after {
  animation: pulse 1s ease-out;
}

@keyframes pulse {
  0% {
    transform: translate(-50%, -50%) scale(1);
    opacity: 1;
  }
  100% {
    transform: translate(-50%, -50%) scale(1.8);
    opacity: 0;
  }
}

.github-icon {
  width: 1rem;
  height: 1rem;
  fill: currentColor;
}

.deploy-checkbox {
  display: none;
}

#rocket-wrapper {
  transition: transform 1.5s ease-out;
}

.deploy-checkbox:checked ~ #rocket-wrapper {
  animation: floatUp 2s ease-out forwards;
}

@keyframes floatUp {
  0% {
    transform: translateY(0);
    opacity: 1;
  }
  100% {
    transform: translateY(-6.25rem);
    opacity: 0;
  }
}
